18	class ReservationServiceTest {
19	
20	    private final SentMessages sentMessages = new SentMessages();
21	    private final ReservationService service = new ReservationService(
22	            new Rooms(), new ReservationStore(), new PriceCalculator(), new EmailSender(sentMessages));
23	
24	    private static NewReservation stay(int roomNumber, String checkIn, String checkOut, int guests, RatePlan plan) {
25	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
26	        return new NewReservation(
27	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
28	    }
29	
30	    private static ErrorCode errorOf(Runnable action) {
31	        return assertThrows(HotelException.class, action::run).errorCode();
32	    }
33	
34	    @Test
35	    void aNewReservationIsPendingWithItsPrice() {
36	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
37	
38	        assertEquals(ReservationStatus.PENDING, reservation.status());
39	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
40	        assertNull(reservation.refund());
41	    }
42	
43	    @Test
44	    void refusesInvalidStays() {
45	        assertEquals(ErrorCode.INVALID_REQUEST,
46	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
47	        assertEquals(ErrorCode.INVALID_REQUEST,
48	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
49	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
50	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
51	        assertEquals(ErrorCode.CAPACITY_EXCEEDED,
52	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD))));
53	    }
54	
55	    @Test
56	    void aRoomCannotBeBookedTwiceForTheSameNight() {
57	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
58	
59	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
60	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
61	        // the check-out day is free for the next guest, and another room is free on the same nights
62	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
63	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
64	    }
65	
66	    @Test
67	    void aCancelledReservationFreesTheRoom() {
68	        Reservation first = service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
69	        service.cancel(first.id());
70	
71	        service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
72	    }
73	
74	    @Test
75	    void confirmingSendsTheReceiptByEmail() {
76	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
77	
78	        service.confirm(reservation.id());
79	
80	        assertEquals(ReservationStatus.CONFIRMED, reservation.status());
81	        List<Message> sent = sentMessages.all();
82	        assertEquals(1, sent.size());
83	        assertEquals("EMAIL", sent.get(0).channel());
84	        assertEquals("ana@example.com", sent.get(0).to());
85	        assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
86	        assertTrue(sent.get(0).body().contains("Desconto: R$ 37,48"));
87	        assertTrue(sent.get(0).body().contains("Total: R$ 212,42"));
88	    }
89	
90	    @Test
91	    void onlyAPendingReservationCanBeConfirmed() {
92	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
93	        service.confirm(reservation.id());
94	
95	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.confirm(reservation.id())));
96	        assertEquals(1, sentMessages.all().size());
97	    }
98	
99	    @Test
100	    void cancellingGivesTheMoneyBackAccordingToTheRatePlan() {
101	        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
102	        Reservation standard = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
103	        Reservation nonRefundable = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
104	        service.confirm(standard.id());
105	        service.confirm(nonRefundable.id());
106	
107	        assertEquals(new BigDecimal("0.00"), service.cancel(pending.id()).refund());
108	        assertEquals(new BigDecimal("249.90"), service.cancel(standard.id()).refund());
109	        assertEquals(new BigDecimal("0.00"), service.cancel(nonRefundable.id()).refund());
110	        assertEquals(ReservationStatus.CANCELLED, standard.status());
111	        assertEquals(new BigDecimal("0.00"), standard.amountKept());
112	        assertEquals(new BigDecimal("331.42"), nonRefundable.amountKept());
113	    }
114	
115	    @Test
116	    void aStayThatStartedCannotBeCancelled() {
117	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
118	        service.confirm(reservation.id());
119	        service.checkIn(reservation.id());
120	
121	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.cancel(reservation.id())));
122	    }
123	
